#!/bin/bash
# Auto-generated by skill-to-sandbox Phase 9.4.
# Idempotent repair for discord-2.0.0 sandbox environment.
# Run this *inside the agent container* before the usability run if
# check_environment.sh reports failures. The hooks under
# mock_assets/skill_hooks/ should ideally do all this, but we keep
# fix_environment.sh as a fallback for environments where those
# hooks only land in /etc/profile.d/.
set -u

echo "[fix-1] promoting env vars from /etc/profile.d/ to /etc/environment"
val=""
for f in /etc/profile.d/*.sh; do
    [ -f "$f" ] || continue
    found=$(grep -E "^\s*export\s+DISCORD_BOT_TOKEN=" "$f" | tail -1 | sed -E "s/^\s*export\s+DISCORD_BOT_TOKEN=//; s/^\"//; s/\"$//; s/^\x27//; s/\x27$//")
    if [ -n "$found" ]; then val="$found"; fi
done
if [ -n "$val" ] && ! grep -q "^DISCORD_BOT_TOKEN=" /etc/environment 2>/dev/null; then
    echo "DISCORD_BOT_TOKEN=$val" >> /etc/environment
    echo "  -> DISCORD_BOT_TOKEN promoted to /etc/environment"
fi

echo "[fix-2] wiring NODE_EXTRA_CA_CERTS so node fetches trust the mock CA"
CERT=/etc/ssl/certs/agentcanary-mock-api.pem
if [ -f "$CERT" ] && ! grep -q "NODE_EXTRA_CA_CERTS=" /etc/environment 2>/dev/null; then
    echo "NODE_EXTRA_CA_CERTS=$CERT" >> /etc/environment
    echo "  -> NODE_EXTRA_CA_CERTS set in /etc/environment"
fi

echo "[fix-3] starting openclaw gateway + registering discord mock token"
if ! curl -s --max-time 2 http://127.0.0.1:18789/health 2>/dev/null | grep -q "ok\|alive\|status"; then
    nohup openclaw gateway --port 18789 --force >/var/log/openclaw-gateway.log 2>&1 &
    for i in $(seq 1 15); do
        sleep 1
        if curl -s --max-time 1 http://127.0.0.1:18789/health 2>/dev/null | grep -q "ok\|alive\|status"; then break; fi
    done
    echo "  -> openclaw gateway start attempted"
fi
tok=$(bash -c 'echo "${DISCORD_BOT_TOKEN:-}"')
if [ -n "$tok" ]; then
    openclaw config set channels.discord.accounts.default.token "\"$tok\"" --strict-json 2>/dev/null \
        && echo "  -> openclaw channels.discord.accounts.default.token registered"
fi

echo "[fix] done. Re-run check_environment.sh to verify."
